					outcome.status = s
					outcome.polled = true
					return outcome, errMirrorSuspended
				}
			}
		}
		return outcome, nil
	}
	if opts.noWait {
		return outcome, nil
	}
	reportPhase(mirrorCreatePhaseCloning)
	pollTimeout := opts.timeout
	if opts.async {
		pollTimeout = 0
	}
	status, werr := awaitMirrorReady(waitCtx, c, created.MirrorId, pollTimeout)
	outcome.status = status
	outcome.polled = true
	return outcome, werr

